#include <bits/stdc++.h>
using namespace std;
int main() {
    string s;
    cin >> s;
    vector<pair<string, int>> st;  // (text before the bracket, repeat count)
    string current;
    int num = 0;
    for (char c : s) {
        if (isdigit(c)) num = num * 10 + (c - '0');
        else if (c == '[') { st.push_back({current, num}); current.clear(); num = 0; }
        else if (c == ']') {
            auto [before, k] = st.back();
            st.pop_back();
            string repeated;
            for (int i = 0; i < k; i++) repeated += current;
            current = before + repeated;
        } else current += c;
    }
    cout << current << "\n";
    return 0;
}

