#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    vector<long long> h(n);
    for (auto& x : h) cin >> x;
    h.push_back(0);  // a final 0 flushes the stack
    vector<int> st;
    long long best = 0;
    for (int i = 0; i <= n; i++) {
        while (!st.empty() && h[st.back()] >= h[i]) {
            int top = st.back(); st.pop_back();
            int left = st.empty() ? 0 : st.back() + 1;
            best = max(best, h[top] * (i - left));
        }
        st.push_back(i);
    }
    cout << best << "\n";
    return 0;
}

